def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    suspicious = []
    ip_counts = {}

    for packet in packet_log:
        ip = packet.get("src_ip")
        if not ip:
            continue

        ip_counts[ip] = ip_counts.get(ip, 0) + 1

        if ip_counts[ip] > 100 or packet.get("dst_port") in {22, 3389}:
            if not any(s.get("src_ip") == ip for s in suspicious):
                suspicious.append(packet)

    return suspicious
