import requests

def test_sql_injection(url: str, params: dict) -> list[str]:
    payloads = ["'", "\"", "' OR '1'='1", "\" OR \"1\"=\"1", "' UNION SELECT NULL--"]
    found_vulnerabilities = []

    for key, original_value in params.items():
        for payload in payloads:
            test_params = params.copy()
            test_params[key] = str(original_value) + payload
            try:
                response = requests.get(url, params=test_params, timeout=5)
                if "sql" in response.text.lower() or "syntax" in response.text.lower() or "mysql" in response.text.lower():
                    found_vulnerabilities.append(f"Parameter '{key}' sårbar med payload: {payload}")
                    break
            except requests.RequestException:
                pass

    return found_vulnerabilities
