def detect_brute_force(auth_log: list[dict], threshold: int = 5) -> list[str]:
    failed = {}
    for entry in auth_log:
        if entry.get("status") == "failed":
            ip = entry.get("ip")
            failed[ip] = failed.get(ip, 0) + 1
    return [ip for ip, count in failed.items() if count >= threshold]
