import pyshark
from collections import Counter
import math

def analyze_dns_traffic(pcap_file: str) -> dict:
    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    queries = []

    capture = pyshark.FileCapture(pcap_file, display_filter='dns.flags.response == 0')

    for packet in capture:
        try:
            q = packet.dns.qry_name
            queries.append(q)

            # DGA: Hög entropi och långt namn
            if len(q) > 15:
                prob = [float(q.count(c)) / len(q) for c in dict.fromkeys(list(q))]
                entropy = -sum(p * math.log(p) / math.log(2.0) for p in prob)
                if entropy > 3.5:
                    suspicious["dga"].append(q)

            # Tunneling: TXT-records eller långa subdomäner
            if hasattr(packet.dns, 'qry_type') and packet.dns.qry_type == '16':
                suspicious["tunneling"].append(q)
            elif q.count('.') > 4:
                suspicious["tunneling"].append(q)

            # Exfiltration: Mycket data i subdomän
            longest_label = max(q.split('.'), key=len)
            if len(longest_label) > 30:
                suspicious["exfiltration"].append(q)

        except AttributeError:
            continue

    capture.close()
    return {k: list(set(v)) for k, v in suspicious.items()}
```

