def harden_ssh_config(config_path: str) -> dict:
    recs = {}
    with open(config_path, 'r') as f:
        config = f.read().lower()

    insecure = {
        "PermitRootLogin": "no",
        "PasswordAuthentication": "no",
        "PermitEmptyPasswords": "no",
        "X11Forwarding": "no",
        "Protocol": "2"
    }

    for key, val in insecure.items():
        if key.lower() not in config:
            recs[key] = val

    return recs
